 ProxySettings *Proxy::proxySettings()
@@ -28,9 +29,34 @@ ProxySettings *Proxy::proxySettings()
     return m_settings;
 }

+// While a VPN is connected, the proxy VPN watcher sets ProxyType to "no proxy" and keeps the real one in
+// ProxyTypeWithoutVpn: show and edit that one instead.
+void Proxy::loadProxyTypeWithoutVpn()
+{
+    const auto group = m_settings->config()->group(u"Proxy Settings"_s);
+    if (!group.hasKey("ProxyTypeWithoutVpn")) {
+        return;
+    }
+    KConfig config(QString(), KConfig::SimpleConfig);
+    config.group(u"Proxy Settings"_s).writeEntry("ProxyType", group.readEntry("ProxyTypeWithoutVpn", 0));
+    m_settings->findItem(u"ProxyType"_s)->readConfig(&config);
+}
+
+void Proxy::load()
+{
+    KQuickManagedConfigModule::load();
+    loadProxyTypeWithoutVpn();
+}
+
 void Proxy::save()
 {
     KQuickManagedConfigModule::save();
+    auto group = m_settings->config()->group(u"Proxy Settings"_s);
+    if (group.hasKey("ProxyTypeWithoutVpn")) {
+        group.writeEntry("ProxyTypeWithoutVpn", m_settings->proxyType());
+        group.writeEntry("ProxyType", 0);
+        group.sync();
+    }
     Q_EMIT showRestartWarning();
     KSaveIOConfig::updateRunningWorkers();
 }
