index 000000000..e6aad617f
--- /dev/null
+++ b/kcms/proxy/vpn-watcher/module.cpp
@@ -0,0 +1,104 @@
+// SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusObjectPath>
+#include <QDBusReply>
+#include <QDBusServiceWatcher>
+#include <QDBusVariant>
+#include <QStandardPaths>
+
+#include <KConfigGroup>
+#include <KDEDModule>
+#include <KDirWatch>
+#include <KPluginFactory>
+#include <KSharedConfig>
+
+using namespace Qt::StringLiterals;
+
+constexpr auto CONFIG_FILE = "kioslaverc"_L1;
+constexpr auto GROUP = "Proxy Settings"_L1;
+constexpr auto PROXY_TYPE = "ProxyType"_L1;
+constexpr auto NO_PROXY_WITH_VPN = "NoProxyWithVpn"_L1;
+constexpr auto PROXY_TYPE_WITHOUT_VPN = "ProxyTypeWithoutVpn"_L1;
+
+constexpr auto NM_SERVICE = "org.freedesktop.NetworkManager"_L1;
+constexpr auto NM_PATH = "/org/freedesktop/NetworkManager"_L1;
+constexpr auto PROPERTIES_INTERFACE = "org.freedesktop.DBus.Properties"_L1;
+
+// While a VPN is connected and the user asked for it, the proxy type is set to "no proxy" and the real one is kept in
+// ProxyTypeWithoutVpn, which the proxy KCM edits instead. It is put back once no VPN is connected anymore.
+class ProxyVpnWatcherModule : public KDEDModule
+{
+    Q_OBJECT
+public:
+    ProxyVpnWatcherModule(QObject *parent, const QList<QVariant> & /*args*/)
+        : KDEDModule(parent)
+    {
+        auto bus = QDBusConnection::systemBus();
+        bus.connect(NM_SERVICE, NM_PATH, PROPERTIES_INTERFACE, u"PropertiesChanged"_s, this, SLOT(update()));
+        auto nmWatcher = new QDBusServiceWatcher(NM_SERVICE, bus, QDBusServiceWatcher::WatchForOwnerChange, this);
+        connect(nmWatcher, &QDBusServiceWatcher::serviceOwnerChanged, this, &ProxyVpnWatcherModule::update);
+
+        const QString configPath = QStandardPaths::writableLocation(QStandardPaths::GenericConfigLocation) + u'/' + CONFIG_FILE;
+        KDirWatch::self()->addFile(configPath);
+        connect(KDirWatch::self(), &KDirWatch::dirty, this, &ProxyVpnWatcherModule::configFileChanged);
+        connect(KDirWatch::self(), &KDirWatch::created, this, &ProxyVpnWatcherModule::configFileChanged);
+
+        update();
+    }
+
+private Q_SLOTS:
+    void configFileChanged(const QString &path)
+    {
+        if (path.endsWith(u'/' + CONFIG_FILE)) {
+            update();
+        }
+    }
+
+    void update()
+    {
+        auto config = KSharedConfig::openConfig(CONFIG_FILE, KConfig::NoGlobals);
+        config->reparseConfiguration();
+        auto group = config->group(GROUP);
+
+        if (group.readEntry(NO_PROXY_WITH_VPN, false) && isVpnConnected()) {
+            const int proxyType = group.readEntry(PROXY_TYPE, 0);
+            if (proxyType != 0) {
+                group.writeEntry(PROXY_TYPE_WITHOUT_VPN, proxyType);
+                group.writeEntry(PROXY_TYPE, 0);
+                config->sync();
+            }
+        } else if (group.hasKey(PROXY_TYPE_WITHOUT_VPN)) {
+            group.writeEntry(PROXY_TYPE, group.readEntry(PROXY_TYPE_WITHOUT_VPN, 0));
+            group.deleteEntry(PROXY_TYPE_WITHOUT_VPN);
+            config->sync();
+        }
+    }
+
+private:
+    static QVariant property(const QString &path, const QString &interface, const QString &name)
+    {
+        auto message = QDBusMessage::createMethodCall(NM_SERVICE, path, PROPERTIES_INTERFACE, u"Get"_s);
+        message << interface << name;
+        const QDBusReply<QDBusVariant> reply = QDBusConnection::systemBus().call(message);
+        return reply.isValid() ? reply.value().variant() : QVariant();
+    }
+
+    static bool isVpnConnected()
+    {
+        const auto activeConnections = qdbus_cast<QList<QDBusObjectPath>>(property(NM_PATH, u"org.freedesktop.NetworkManager"_s, u"ActiveConnections"_s));
+        for (const auto &connection : activeConnections) {
+            const QString interface = u"org.freedesktop.NetworkManager.Connection.Active"_s;
+            if (property(connection.path(), interface, u"Vpn"_s).toBool() || property(connection.path(), interface, u"Type"_s).toString() == "wireguard"_L1) {
+                return true;
+            }
+        }
+        return false;
+    }
+};
+
+K_PLUGIN_CLASS_WITH_JSON(ProxyVpnWatcherModule, "proxy-vpn-watcher.json")
+
+#include "module.moc"
